gh api graphql -f query='
query {
  repository(owner: "chief-builder-lab", name: "clivsmcp-tier1-issue-triage-21251841") {
    issues(states: OPEN, first: 50) {
      nodes {
        number
        title
        body
        labels(first: 20) {
          nodes {
            name
          }
        }
      }
    }
  }
}' --jq '.data.repository.issues.nodes[] | {number, title, body, labels: [.labels.nodes[].name]}'

gh api graphql -f query='
query {
  repository(owner: "chief-builder-lab", name: "clivsmcp-tier1-issue-triage-21251841") {
    name
    issues(states: OPEN, first: 50) {
      totalCount
    }
  }
}' 2>&1

